O=pathlib.Path(__file__).resolve().parent;ROOT=O.parents[4];W=O.parent/'public_water'/'frozen_r01';read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();g=PublicGraph();rs=read(O/'observed_residential_access_ledger.json');water=read(W/'routes.json');market=next(x for x in read(O/'observed_water_drawpoints.json') if x['id']=='MARKET_DRAW');base_d=g.distances(market['station']);base=np.array([g.from_station(r['station'],base_d) for r in rs]);cur_d=base_d.copy();candidates=[]
